-- Admin/member and audited expense management for the complete pilot UI.
create or replace function public.add_manual_member(p_vibe uuid,p_actor uuid,p_token text,p_name text)
returns uuid language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare a members;m members;n integer;begin a:=vm_authorize(p_vibe,p_actor,p_token,true);select count(*) into n from members where vibe_id=p_vibe;if n>=(select max_members from vibes where id=p_vibe) then raise exception 'vibe_full';end if;insert into members(vibe_id,display_name,created_by_member_id) values(p_vibe,trim(p_name),p_actor) returning * into m;insert into activity(vibe_id,actor_member_id,actor_name_snapshot,action_type,entity_type,entity_id,new_data) values(p_vibe,p_actor,a.display_name,'member_added','member',m.id,jsonb_build_object('name',m.display_name));return m.id;end$$;
create or replace function public.delete_expense(p_vibe uuid,p_actor uuid,p_token text,p_expense uuid)
returns void language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare a members;e expenses;begin a:=vm_authorize(p_vibe,p_actor,p_token,false);select * into e from expenses where id=p_expense and vibe_id=p_vibe and deleted_at is null;if not found then raise exception 'expense_unavailable';end if;insert into expense_versions(expense_id,vibe_id,version_number,snapshot,changed_by_member_id) values(e.id,p_vibe,1,to_jsonb(e),p_actor);update expenses set deleted_at=now(),deleted_by_member_id=p_actor where id=e.id;insert into activity(vibe_id,actor_member_id,actor_name_snapshot,action_type,entity_type,entity_id,old_data) values(p_vibe,p_actor,a.display_name,'expense_deleted','expense',e.id,to_jsonb(e));end$$;
create or replace function public.archive_vibe(p_vibe uuid,p_actor uuid,p_token text)
returns void language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare a members;begin a:=vm_authorize(p_vibe,p_actor,p_token,true);update vibes set is_archived=true,updated_at=now() where id=p_vibe;insert into activity(vibe_id,actor_member_id,actor_name_snapshot,action_type,entity_type,entity_id) values(p_vibe,p_actor,a.display_name,'vibe_archived','vibe',p_vibe);end$$;
grant execute on function public.add_manual_member(uuid,uuid,text,text),public.delete_expense(uuid,uuid,text,uuid),public.archive_vibe(uuid,uuid,text) to anon;
